import{_ as i,c as n,o as t,ae as r}from"./chunks/framework.CHDT0Kbg.js";const b=JSON.parse('{"title":"Fehlerbehebung","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/troubleshooting.md","filePath":"de/guide/troubleshooting.md","lastUpdated":1795170900000}'),a={name:"de/guide/troubleshooting.md"};function o(l,e,s,d,h,u){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="fehlerbehebung" tabindex="-1">Fehlerbehebung <a class="header-anchor" href="#fehlerbehebung" aria-label="Permalink to &quot;Fehlerbehebung&quot;">​</a></h1><p>Lösungen für häufige Probleme.</p><h2 id="eine-seite-ladt-nicht" tabindex="-1">Eine Seite lädt nicht <a class="header-anchor" href="#eine-seite-ladt-nicht" aria-label="Permalink to &quot;Eine Seite lädt nicht&quot;">​</a></h2><ul><li>Prüfe, ob andere Seiten funktionieren, und lade mit ⌘R neu.</li><li>Wenn eine Werbeblockier-Liste aktiv ist, pausiere sie kurz, um zu sehen, ob sie die Seite blockiert.</li><li>Versuche ein privates Fenster (⌘⇧N). Funktioniert die Seite dort, lösche die Cookies der Seite in den Einstellungen.</li></ul><h2 id="download-bleibt-hangen-oder-ist-unvollstandig" tabindex="-1">Download bleibt hängen oder ist unvollständig <a class="header-anchor" href="#download-bleibt-hangen-oder-ist-unvollstandig" aria-label="Permalink to &quot;Download bleibt hängen oder ist unvollständig&quot;">​</a></h2><ul><li>Öffne das Download-Panel, pausiere den Vorgang und setze ihn fort.</li><li>Lösche bei einem fehlgeschlagenen Video-Download die unvollständige Datei und versuche es erneut. Geteilte Videos werden zu einer MP4 zusammengefügt; bei einem Fehler bleiben die Teile im Download-Ordner.</li></ul><h2 id="lesezeichen-wurden-nicht-importiert" tabindex="-1">Lesezeichen wurden nicht importiert <a class="header-anchor" href="#lesezeichen-wurden-nicht-importiert" aria-label="Permalink to &quot;Lesezeichen wurden nicht importiert&quot;">​</a></h2><p>Exportiere zuerst die Lesezeichen deines alten Browsers als HTML-Datei und wähle dann in Persim <strong>HTML importieren</strong> im Lesezeichen-Manager. Ordner und doppelte Links werden automatisch sortiert.</p><h2 id="videos-werden-nicht-erkannt" tabindex="-1">Videos werden nicht erkannt <a class="header-anchor" href="#videos-werden-nicht-erkannt" aria-label="Permalink to &quot;Videos werden nicht erkannt&quot;">​</a></h2><p>Nicht jede Website stellt eine speicherbare Videodatei bereit. Öffne das Medien-Panel auf der Seite. Wenn nichts erscheint, lässt sich das Video dort nicht direkt speichern.</p><h2 id="die-app-ist-langsam" tabindex="-1">Die App ist langsam <a class="header-anchor" href="#die-app-ist-langsam" aria-label="Permalink to &quot;Die App ist langsam&quot;">​</a></h2><p>Schließe nicht mehr benötigte Tabs oder deaktiviere ein Abo zur Werbeblockierung. Website-Berechtigungen kannst du in den Einstellungen prüfen.</p><h2 id="immer-noch-kein-erfolg" tabindex="-1">Immer noch kein Erfolg? <a class="header-anchor" href="#immer-noch-kein-erfolg" aria-label="Permalink to &quot;Immer noch kein Erfolg?&quot;">​</a></h2><p>Schreibe an <strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong> und beschreibe, was du tun wolltest — am besten mit einem Screenshot.</p>',14)])])}const m=i(a,[["render",o]]);export{b as __pageData,m as default};
